using System;
using System.Collections.Generic;
using UnityEngine;

namespace GPA.TopDown2D
{
    /// <summary>
    /// The city's location records: streets, intersections, buildings with addresses, districts
    /// and incident spawn spots. Generated by the city builder and saved as an asset so the map,
    /// dispatch, callouts and MDT all agree on names. Nothing here is regenerated at runtime.
    /// </summary>
    [CreateAssetMenu(menuName = "GPA/City Location Database")]
    public sealed class CityLocationDatabase : ScriptableObject
    {
        [Serializable]
        public sealed class Street
        {
            public string Name;
            public string Abbrev;
            public bool Vertical;          // runs north-south
            public Rect Bounds;            // world-space asphalt area
            [Tooltip("two-way, north, south, east or west")]
            public string Direction = "two-way";
            public string District;
        }

        [Serializable]
        public sealed class Intersection
        {
            public string Name;
            public Vector2 Position;
            public string StreetA;
            public string StreetB;
        }

        [Serializable]
        public sealed class Building
        {
            public string Id;              // e.g. "HP-0042"
            public string Name;            // e.g. "Apartment building", "1st Precinct"
            public string Type;            // apartment, office, shop, police, park, ...
            public int Number;             // street number
            public string Street;
            public string District;
            public Rect Footprint;
            public Vector2 Entrance;       // on the sidewalk in front
            public int Floors = 1;
            public string Address => $"{Number} {Street}";
        }

        [Serializable]
        public sealed class District
        {
            public string Name;
            public string Borough;
            public Rect Bounds;
        }

        public string CityName = "New Halden";
        public List<District> Districts = new List<District>();
        public List<Street> Streets = new List<Street>();
        public List<Intersection> Intersections = new List<Intersection>();
        public List<Building> Buildings = new List<Building>();
        /// <summary>Drivable ground in world metres: the island, the districts over the bridges, and the bridges.</summary>
        public List<Rect> Land = new List<Rect>();

        public bool IsLand(Vector2 p)
        {
            if (Land.Count == 0) return true;
            foreach (var r in Land) if (r.Contains(p)) return true;
            return false;
        }

        public Building FindBuilding(string id) => Buildings.Find(b => b.Id == id);

        public Building NearestBuilding(Vector2 p, float maxDistance)
        {
            Building best = null;
            float bestD = maxDistance;
            foreach (var b in Buildings)
            {
                float d = Vector2.Distance(ClosestPoint(b.Footprint, p), p);
                if (d < bestD) { bestD = d; best = b; }
            }
            return best;
        }

        public Street StreetAt(Vector2 p, float tolerance = 2f)
        {
            Street best = null;
            float bestD = tolerance;
            foreach (var s in Streets)
            {
                float d = Vector2.Distance(ClosestPoint(s.Bounds, p), p);
                if (d < bestD || (d == 0f && best != null && Area(s.Bounds) < Area(best.Bounds))) { bestD = d; best = s; }
            }
            return best;
        }

        public Intersection NearestIntersection(Vector2 p)
        {
            Intersection best = null;
            float bestD = float.MaxValue;
            foreach (var i in Intersections)
            {
                float d = (i.Position - p).sqrMagnitude;
                if (d < bestD) { bestD = d; best = i; }
            }
            return best;
        }

        public District DistrictAt(Vector2 p)
        {
            foreach (var d in Districts) if (d.Bounds.Contains(p)) return d;
            return Districts.Count > 0 ? Districts[0] : null;
        }

        private static float Area(Rect r) => r.width * r.height;

        public static Vector2 ClosestPoint(Rect r, Vector2 p) =>
            new Vector2(Mathf.Clamp(p.x, r.xMin, r.xMax), Mathf.Clamp(p.y, r.yMin, r.yMax));
    }
}
